#include <gtest/gtest.h>
#include "m1_local_fast2d/candidate_risk_scorer.hpp"
namespace { m1_scope_risk::RiskFieldSnapshot snap(){m1_scope_msgs::msg::ScopePredictionSequence s;s.header.frame_id="odom";s.header.stamp.sec=100;s.prediction_id=8;for(int i=1;i<=10;i++){m1_scope_msgs::msg::ScopePredictionSlice z;z.time_from_start.sec=i/10;z.time_from_start.nanosec=(i%10)*100000000;for(auto*g:{&z.probability,&z.uncertainty}){g->header.frame_id="odom";g->header.stamp.sec=100+z.time_from_start.sec;g->header.stamp.nanosec=z.time_from_start.nanosec;g->info.resolution=1;g->info.width=2;g->info.height=1;g->info.origin.orientation.w=1;g->data={10,10};}if(i==6)z.probability.data[0]=80;s.slices.push_back(z);}return *m1_scope_risk::RiskFieldSnapshot::fromMessage(s,{});}m1_local_fast2d::msg::TimedTrajectory traj(double x){m1_local_fast2d::msg::TimedTrajectory t;t.planning_result_id=4;for(int i=0;i<=10;i++){m1_local_fast2d::msg::TimedTrajectoryPoint p;p.x=x;p.y=0.2;p.time_from_start=i*.1;t.points.push_back(p);}return t;}}
TEST(CandidateRiskScorer, AbsoluteTimeAndRouteDiscriminate){auto s=snap();auto high=m1_local_fast2d::CandidateRiskScorer::score(traj(.2),0,s,100000000000LL,100100000000LL,{});auto low=m1_local_fast2d::CandidateRiskScorer::score(traj(1.2),1,s,100000000000LL,100100000000LL,{});EXPECT_TRUE(high.score_valid);EXPECT_GT(high.max_risk,low.max_risk);EXPECT_GT(high.mean_risk,low.mean_risk);}
TEST(CandidateRiskScorer, PlanningOffsetUsesAbsoluteTimeAndCoverage){auto s=snap();auto early_t=traj(.2);early_t.points.resize(2);auto late_t=early_t;auto early=m1_local_fast2d::CandidateRiskScorer::score(early_t,0,s,100100000000LL,100200000000LL,{});auto late=m1_local_fast2d::CandidateRiskScorer::score(late_t,1,s,100500000000LL,100400000000LL,{});EXPECT_GT(late.max_risk,early.max_risk);auto long_t=traj(1.2);long_t.points.back().time_from_start=3.;auto c=m1_local_fast2d::CandidateRiskScorer::score(long_t,2,s,100000000000LL,100100000000LL,{});EXPECT_NEAR(c.coverage_ratio,1./3.,.05);}
